update public.quizzes set questions = $quiz$[{"correct": 1, "options": ["2021", "March 2022", "November 2022", "2023"], "fun_fact": "(G)I-DLE released 'I NEVER DIE' on March 14, 2022, their first album as a 5-member group after Soojin's departure in August 2021.", "question": "When was (G)I-DLE's 'I NEVER DIE' album (TOMBOY era) released?"}, {"correct": 2, "options": ["HWAA", "Nxde", "TOMBOY", "MY BAG"], "fun_fact": "'TOMBOY' became one of (G)I-DLE's most iconic songs -- a defiant anthem about rejecting labels and societal expectations.", "question": "What was the lead single from 'I NEVER DIE'?"}, {"correct": 1, "options": ["Romantic love", "Defiance of gender norms and labels, doing whatever you want", "Grief and loss", "Patriotism"], "fun_fact": "'TOMBOY' is a powerful statement about rejecting labels -- 'Don't call me baby' -- expressing freedom from societal expectations.", "question": "What themes define 'TOMBOY'?"}, {"correct": 3, "options": ["First K-pop song by a girl group to chart for 10 weeks at #1 on Melon simultaneously in multiple countries", "It became the best-selling single of 2022 in Korea", "It debuted at #1 on Billboard Hot 100", "It won Song of the Year at every major Korean awards show"], "fun_fact": "'TOMBOY' swept major awards at 2022 Korean year-end ceremonies, winning Song of the Year at multiple shows.", "question": "What milestone did 'TOMBOY' achieve in South Korea?"}, {"correct": 2, "options": ["Violin", "Guitar", "Piano", "Drums"], "fun_fact": "Minnie is a trained pianist who often performs on piano during (G)I-DLE's live stages and concert performances.", "question": "What instrument does Minnie play in (G)I-DLE's live performances?"}, {"correct": 1, "options": ["Miyeon", "Soyeon", "Minnie", "Shuhua"], "fun_fact": "Soyeon is the central creative force in (G)I-DLE, writing, composing, and producing most of the group's discography since debut.", "question": "Which (G)I-DLE member is the primary songwriter and producer?"}, {"correct": 1, "options": ["6", "5", "4", "7"], "fun_fact": "After Soojin's departure in 2021, (G)I-DLE continued as a 5-member group: Miyeon, Minnie, Soyeon, Yuqi, and Shuhua.", "question": "How many members does (G)I-DLE have during the TOMBOY era?"}, {"correct": 1, "options": ["Already", "VILLAIN DIES", "My Bag", "Oh My God"], "fun_fact": "'VILLAIN DIES' became an acclaimed performance track from I NEVER DIE, praised for Soyeon's dynamic rapping and Miyeon's powerful vocals.", "question": "What fan-favorite track from I NEVER DIE became a concert staple?"}, {"correct": 2, "options": ["Best Choreography", "Artist of the Year", "Best Female Group", "Song of the Year"], "fun_fact": "The I NEVER DIE era solidified (G)I-DLE as the top girl group of 2022, culminating in major award wins including Best Female Group at MAMAs.", "question": "What award did (G)I-DLE win at the 2022 Mnet Asian Music Awards?"}, {"correct": 1, "options": ["Latata era", "HWAA era", "Oh My God era", "Lion era"], "fun_fact": "The 'HWAA' era (2021) featured traditional imagery including hanbok-inspired visuals, before TOMBOY's bold contemporary concept pivot.", "question": "What era preceded TOMBOY that showed (G)I-DLE's traditional/ethnic concept?"}]$quiz$::jsonb
where id = 'e9d14fb3-d6a3-43f6-9617-0bdb5daab8df' and slug = 'gi-dle-the-tomboy-era';

