update public.quizzes set questions = $quiz$[{"correct": 2, "options": ["BLACKPINK - DDU-DU DDU-DU", "PSY - Gangnam Style", "BTS - Dynamite", "BLACKPINK - Kill This Love"], "fun_fact": "BTS's Dynamite became the first K-pop song to surpass 1 billion streams on Spotify on July 20, 2021. It also later became the first K-pop song to surpass 2 billion streams.", "question": "Which K-pop song was the first by any K-pop act to surpass 1 billion streams on Spotify?"}, {"correct": 3, "options": ["TWICE", "aespa", "Girls' Generation", "BLACKPINK"], "fun_fact": "BLACKPINK held the title of Spotify's most-streamed girl group globally every year from 2019 through 2023, accumulating over 10 billion streams all-time.", "question": "Which K-pop girl group was named Spotify's most-streamed girl group globally for five consecutive years from 2019 to 2023?"}, {"correct": 1, "options": ["Spotify US Top 50", "Spotify Global Daily Top Songs", "Spotify Viral 50", "Spotify New Music Friday"], "fun_fact": "BTS's Dynamite became the first song by a Korean artist to debut at number one on Spotify's Daily Top Songs Global chart upon its release in August 2020.", "question": "Dynamite by BTS debuted at number one on which Spotify chart, a historic first for a K-pop act?"}, {"correct": 1, "options": ["First K-pop song to reach 1 billion streams", "First K-pop girl group song to reach 1 billion Spotify streams", "First girl group song to debut at #1 on Spotify Global", "First K-pop song to enter the Spotify top 10"], "fun_fact": "How You Like That became the first K-pop girl group song to surpass 1 billion streams on Spotify, reaching the milestone in March 2024.", "question": "BLACKPINK's How You Like That reached 1 billion Spotify streams. What milestone did it achieve as a K-pop girl group song?"}, {"correct": 1, "options": ["November 2012", "December 2012", "January 2013", "March 2013"], "fun_fact": "Gangnam Style became the first YouTube video to reach 1 billion views on December 21, 2012. It was also the first video to reach 2 billion, 3 billion, and eventually even broke YouTube's view counter.", "question": "PSY's Gangnam Style was the first YouTube video to reach 1 billion views. When did it achieve this milestone?"}, {"correct": 2, "options": ["Boy With Luv", "DNA", "Dynamite", "Butter"], "fun_fact": "BTS's Dynamite became the first K-pop song to surpass 2 billion streams on Spotify on August 10, 2024, continuing its historic streaming records.", "question": "Which BTS song became the first K-pop song to surpass 2 billion streams on Spotify?"}, {"correct": 0, "options": ["ENHYPEN", "ATEEZ", "TXT", "Stray Kids"], "fun_fact": "ENHYPEN set the record for the most-streamed K-pop boy group debut on Spotify, with their debut EP Border: Day One accumulating record streams in 2020.", "question": "Which K-pop boy group set a record for most-streamed K-pop debut on Spotify?"}, {"correct": 1, "options": ["Most streams in one week by K-pop group", "Longest-charting song by a K-pop female act (42 weeks)", "First K-pop girl group song at #1", "Most-streamed debut song ever"], "fun_fact": "Hype Boy spent 42 weeks on the Billboard Global 200, setting the record for the longest-charting song by a K-pop girl group on that chart.", "question": "NewJeans' Hype Boy broke which streaming record on the Billboard Global 200?"}, {"correct": 1, "options": ["5.5 billion", "8.8 billion", "12 billion", "3.2 billion"], "fun_fact": "BLACKPINK surpassed 8.8 billion streams to claim the Guinness record for most-streamed female band on Spotify, beating previous titleholders Little Mix.", "question": "BLACKPINK set a Guinness World Record in 2023 by becoming the most-streamed female band on Spotify. How many streams did they have at that point?"}, {"correct": 2, "options": ["Twitter/X", "Instagram", "TikTok", "YouTube Shorts"], "fun_fact": "NewJeans songs like Hype Boy, Ditto, and OMG went massively viral on TikTok in 2022-2023, exposing their music to global audiences beyond traditional K-pop fans.", "question": "Which social media platform was instrumental in launching NewJeans to global fame, with their songs going viral in 2022-2023?"}]$quiz$::jsonb
